// Generated by scripts/sync-film.mjs from motion-film/src/kit/Idle.tsx. Edit it there, then run `npm run sync:film`.
import React from "react";
import { useCurrentFrame } from "remotion";
import { wave } from "./motion";

/** Pendulum sway about the bottom-centre (hung paper, standing figures). */
export const Sway: React.FC<{ amp?: number; period?: number; phase?: number; origin?: string; children: React.ReactNode; style?: React.CSSProperties }> = ({
  amp = 0.6,
  period = 150,
  phase = 0,
  origin = "50% 100%",
  children,
  style,
}) => {
  const frame = useCurrentFrame();
  return <div style={{ transform: `rotate(${wave(frame, period, phase) * amp}deg)`, transformOrigin: origin, ...style }}>{children}</div>;
};

/** Gentle vertical float. */
export const Bob: React.FC<{ amp?: number; period?: number; phase?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({
  amp = 6,
  period = 120,
  phase = 0,
  children,
  style,
}) => {
  const frame = useCurrentFrame();
  return <div style={{ transform: `translateY(${wave(frame, period, phase) * amp}px)`, ...style }}>{children}</div>;
};

/**
 * Renders children as a flat dark silhouette (shadow-puppet screens, distant crowds).
 * Uses filter + opacity only — no blend modes (they band over composited layers).
 */
export const Silhouette: React.FC<{ opacity?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({
  opacity = 0.88,
  children,
  style,
}) => <div style={{ filter: "brightness(0)", opacity, ...style }}>{children}</div>;
